package com.bank.agg;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BranchAggregationDemo {
    private static final Logger log = Logger.getLogger(BranchAggregationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        log.info(() -> "Aggregation context acct " + rajesh.getAccountId());

        BranchAggregationService svc = new BranchAggregationService();

        // Rectangular: 3 branches x 4 quarters, all zeros to start.
        int[][] grid = svc.quarterlyGrid(3, 4);
        grid[0][0] = 120; grid[0][3] = 95; grid[1][1] = 60; grid[2][2] = 30;
        log.info(() -> "rectangular grid = " + Arrays.deepToString(grid));
        log.info(() -> "grid.length (rows) = " + grid.length
                + ", grid[0].length (cols) = " + grid[0].length);

        // Jagged: each branch has a different number of daily transactions.
        int[][] jagged = svc.dailyJagged();
        log.info(() -> "jagged = " + Arrays.deepToString(jagged));
        log.info(() -> "row lengths = " + jagged[0].length + ", "
                + jagged[1].length + ", " + jagged[2].length);

        // Row totals walk each contiguous row fully (cache-friendly order).
        int[] totals = svc.rowTotals(jagged);
        log.info(() -> "jagged row totals = " + Arrays.toString(totals));

        // deepEquals compares nested content; shallow equals would not.
        int[][] copy = svc.dailyJagged();
        log.info(() -> "deepEquals = " + Arrays.deepEquals(jagged, copy)
                + ", shallow equals = " + Arrays.equals(jagged, copy));
    }
}

