class BranchAggregationService {
    private static final Logger log = Logger.getLogger(BranchAggregationService.class.getName());

    // Rectangular: new int[rows][cols] allocates every row as zeros.
    int[][] quarterlyGrid(int branches, int quarters) {
        return new int[branches][quarters];
    }

    // Jagged: outer refs start null; assign each row its own length.
    int[][] dailyJagged() {
        int[][] jagged = new int[3][];       // 3 null rows
        jagged[0] = new int[] {10, 20, 30};  // Mumbai: 3 txns
        jagged[1] = new int[] {5, 15};       // Pune: 2 txns
        jagged[2] = new int[] {40};          // small branch: 1 txn
        return jagged;
    }

    // Walk each row fully (outer=rows, inner=cols) — cache-friendly.
    int[] rowTotals(int[][] data) {
        int[] totals = new int[data.length];
        for (int r = 0; r < data.length; r++) {
            if (data[r] == null) {           // guard against unassigned rows
                log.warning("Null row " + r + " skipped");
                continue;
            }
            int sum = 0;
            for (int c = 0; c < data[r].length; c++) {
                sum += data[r][c];
            }
            totals[r] = sum;
        }
        return totals;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
